def eliminate_maximum_monsters(dist, speed):
    latest_minutes = sorted((distance - 1) // velocity for distance, velocity in zip(dist, speed))
    for minute, latest in enumerate(latest_minutes):
        if latest < minute:
            return minute
    return len(latest_minutes)

